export default function(){

    for (let datum of data) {
        if (datum.id) {
            ActorTypeUtil.registerActorType(datum as any);
        }
    }

    for (let datum of data) {
        if (datum.itemMaterialsFormula) {
            SolarNewItemsFormulaState.config[datum.id] = {material: datum.itemMaterialsFormula}
        }
    }
}
